      current: 'Hoy no mostramos anuncios. Todas las páginas de boardly.online cargan el script de AdSense de Google, que permite a Google confirmar que el sitio es nuestro y muestra el mensaje de consentimiento de Google a los visitantes del EEE y del Reino Unido. El script guarda una cookie en tu dispositivo (FCCDCF) para registrar el mensaje y tu respuesta. Google trata estos datos como responsable del tratamiento independiente conforme a su propia política de privacidad.',
