      delete: 'Elimina tu cuenta desde tu página de perfil, en el navegador o en la app de Android: elige "Eliminar cuenta" en "Zona de peligro" y confírmalo con el enlace que te enviamos por correo electrónico. Esto también elimina tu foto de perfil, sustituye tu nombre por "Jugador eliminado" en los registros de partidas y repeticiones de los demás jugadores, conserva los comentarios que enviaste pero les quita tu dirección de correo y tu cuenta y elimina su copia en nuestro canal de comentarios de Discord, y cancela cualquier suscripción y elimina tu ficha de cliente en Stripe. Las denuncias que presentaste y las denuncias sobre ti pierden su vínculo con tu cuenta; la copia del contenido denunciado se conserva durante el periodo de la denuncia. Si ya no puedes iniciar sesión, escribe a {{email}} desde la dirección de la cuenta y la eliminamos por ti.',
      forget: 'Invitados: "Olvidarme" en el menú de invitado elimina tu registro de invitado y tus puestos en las partidas, sustituye tu nombre por "Jugador eliminado" en los registros de los demás jugadores y borra los datos de invitado de este dispositivo. Si estás sentado en una partida en curso, termínala o sal de ella primero.',
