      required: 'Para crear una cuenta necesitas una dirección de correo electrónico y una contraseña, o un proveedor de inicio de sesión; puedes jugar como invitado sin ninguno de ellos. No tomamos decisiones sobre ti basadas únicamente en un tratamiento automatizado.',
